Set-StrictMode -Version Latest

function Read-TaskStore {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path)) {
        return @()
    }

    $content = Get-Content -LiteralPath $Path -Raw
    if ([string]::IsNullOrWhiteSpace($content)) {
        return @()
    }

    $parsed = ConvertFrom-Json -InputObject $content
    return @($parsed)
}

function Write-TaskStore {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
    )

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    $temporary = "$Path.$PID.tmp"
    $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
    [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
    Move-Item -LiteralPath $temporary -Destination $Path -Force
}

function Read-TaskCsv {
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "CSV file was not found: $Path"
    }

    $parser = [Microsoft.VisualBasic.FileIO.TextFieldParser]::new($Path)
    try {
        $parser.TextFieldType = [Microsoft.VisualBasic.FileIO.FieldType]::Delimited
        $parser.SetDelimiters(',')
        $parser.HasFieldsEnclosedInQuotes = $true
        if ($parser.EndOfData) {
            throw 'CSV must include a Title column.'
        }
        $propertyNames = @($parser.ReadFields())
    }
    finally {
        $parser.Dispose()
    }

    if ($propertyNames -notcontains 'Title') {
        throw 'CSV must include a Title column.'
    }

    $rows = @(Import-Csv -LiteralPath $Path)
    for ($index = 0; $index -lt $rows.Count; $index++) {
        $rowNumber = $index + 2
        if ([string]::IsNullOrWhiteSpace([string]$rows[$index].Title)) {
            throw "CSV row $rowNumber has a blank Title."
        }

        $status = if ($propertyNames -contains 'Status') { ([string]$rows[$index].Status).Trim() } else { '' }
        if ($status -notin @('', 'pending', 'completed')) {
            throw "CSV row $rowNumber has invalid Status '$status'."
        }
    }

    return $rows
}

function ConvertFrom-TaskForgeArguments {
    param([AllowEmptyCollection()][string[]]$Arguments)

    $options = [ordered]@{}
    for ($index = 0; $index -lt $Arguments.Count; $index++) {
        $token = $Arguments[$index]
        if (-not $token.StartsWith('--')) {
            throw "Unexpected argument: $token"
        }

        $name = $token.Substring(2)
        if ([string]::IsNullOrWhiteSpace($name)) {
            throw 'Option name cannot be empty.'
        }
        if ($options.Contains($name)) {
            throw "Duplicate option: --$name"
        }

        if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
            $options[$name] = $Arguments[++$index]
        }
        else {
            $options[$name] = $true
        }
    }

    return $options
}

function Get-RequiredOption {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][string]$Name
    )

    if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
        [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
        throw "Missing required option: --$Name"
    }
    return [string]$Options[$Name]
}

function Assert-KnownOptions {
    param(
        [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
    )

    foreach ($name in $Options.Keys) {
        if ($name -notin $Allowed) {
            throw "Unknown option: --$name"
        }
    }
}

function Write-TaskForgeOutput {
    param(
        [Parameter(Mandatory)]$Value,
        [Parameter(Mandatory)][bool]$AsJson
    )

    if ($AsJson) {
        ConvertTo-Json -InputObject $Value -Depth 8 -Compress
    }
    else {
        [string]$Value
    }
}

Export-ModuleMember -Function *

[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $options = ConvertFrom-TaskForgeArguments -Arguments $CliArguments
    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    else {
        $defaultDataFile
    }
    $asJson = $options.Contains('json')

    switch ($Command.ToLowerInvariant()) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'json')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'import-csv' {
            Assert-KnownOptions -Options $options -Allowed @('path', 'data-file', 'json')
            $csvPath = Get-RequiredOption -Options $options -Name 'path'
            $rows = @(Read-TaskCsv -Path $csvPath)
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            $imported = @(
                foreach ($row in $rows) {
                    [pscustomobject][ordered]@{
                        id = $nextId++
                        title = ([string]$row.Title).Trim()
                        description = if ($row.PSObject.Properties.Name -contains 'Description') {
                            [string]$row.Description
                        }
                        else {
                            ''
                        }
                        status = if ($row.PSObject.Properties.Name -notcontains 'Status' -or
                            [string]::IsNullOrWhiteSpace([string]$row.Status)) {
                            'pending'
                        }
                        else {
                            ([string]$row.Status).Trim()
                        }
                        createdAt = $createdAt
                    }
                }
            )
            Write-TaskStore -Path $dataFile -Tasks @($tasks + $imported)
            $summary = [pscustomobject][ordered]@{
                importedCount = $imported.Count
                importedIds = @($imported | ForEach-Object { $_.id })
            }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                Get-Content -LiteralPath (Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/import.txt')
                "Imported $($summary.importedCount) task(s): $($summary.importedIds -join ', ')"
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @()
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json]
  list [--data-file PATH] [--json]
  complete --id ID [--data-file PATH] [--json]
  remove --id ID [--data-file PATH] [--json]
  import-csv --path PATH [--data-file PATH] [--json]
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
